import type { RecipeStep } from '@bmad/shared/types';

interface RecipeStepsProps {
  steps: RecipeStep[];
}

export default function RecipeSteps({ steps }: RecipeStepsProps) {
  const [currentStep, setCurrentStep] = useState<number | null>(null);

  const sortedSteps = [...steps].sort((a, b) => a.stepNumber - b.stepNumber);

  const toggleCookingMode = () => {
    if (currentStep === null) {
      setCurrentStep(1);
    } else {
      setCurrentStep(null);
    }
  };

  const nextStep = () => {
    if (currentStep !== null && currentStep < sortedSteps.length) {
      setCurrentStep(currentStep + 1);
    }
  };

  const previousStep = () => {
    if (currentStep !== null && currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold">Instructions</h2>
        <button
          onClick={toggleCookingMode}
          className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
            currentStep !== null
              ? 'bg-blue-600 text-white hover:bg-blue-700'
              : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
          }`}
        >
          {currentStep !== null ? 'Exit Cooking Mode' : 'Cooking Mode'}
        </button>
      </div>

      {currentStep !== null && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-blue-900">
              Step {currentStep} of {sortedSteps.length}
            </span>
            <div className="flex gap-2">
              <button
                onClick={previousStep}
                disabled={currentStep === 1}
                className="px-3 py-1 text-sm bg-white border border-blue-300 rounded hover:bg-blue-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Previous
